/* Base Styles & Variables */
:root {
  --bg-main: #0A0A0A;
  --bg-subtle: #141414;
  --bg-card: #1E1E1E;
  --bg-hover: #2A2A2A;

  --text-main: #FFFFFF;
  --text-muted: #A0A0A0;

  --accent: #3b82f6; /* Electric blue */
  --accent-hover: #2563eb;

  --border: #333333;
  --radius: 8px;
  --radius-lg: 16px;

  --transition: all 0.3s ease;
  --font-main: 'Inter', sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-main);
  background-color: var(--bg-main);
  color: var(--text-main);
  line-height: 1.6;
  overflow-x: hidden;
}

a {
  text-decoration: none;
  color: inherit;
  transition: var(--transition);
}

img {
  max-width: 100%;
  display: block;
}

.container {
  width: 100%;
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 5%;
}

.text-center {
  text-align: center;
}

.bg-subtle {
  background-color: var(--bg-subtle);
}

.hidden {
  display: none !important;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-weight: 600;
  line-height: 1.2;
}

.section-title {
  font-size: 2.5rem;
  margin-bottom: 1rem;
  letter-spacing: -0.02em;
}

.section-subtitle {
  font-size: 1.125rem;
  color: var(--text-muted);
  max-width: 600px;
  margin-bottom: 3rem;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.75rem 1.5rem;
  font-weight: 500;
  border-radius: var(--radius);
  cursor: pointer;
  transition: var(--transition);
  border: none;
  font-size: 1rem;
}

.btn-primary {
  background-color: var(--accent);
  color: white;
}

.btn-primary:hover {
  background-color: var(--accent-hover);
}

.btn-secondary {
  background-color: white;
  color: var(--bg-main);
}

.btn-secondary:hover {
  background-color: #f0f0f0;
}

.btn-outline {
  background-color: transparent;
  border: 1px solid var(--border);
  color: var(--text-main);
}

.btn-outline:hover {
  border-color: var(--text-muted);
}

.btn-text {
  background-color: transparent;
  color: var(--text-muted);
}

.btn-text:hover {
  color: var(--text-main);
}

.btn-large {
  padding: 1rem 2rem;
  font-size: 1.125rem;
}

.btn-sm {
  padding: 0.5rem 1rem;
  font-size: 0.875rem;
}

/* Sections */
.section {
  padding: 6rem 0;
}

/* Navigation */
.navbar {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 80px;
  background-color: rgba(10, 10, 10, 0.8);
  backdrop-filter: blur(12px);
  z-index: 100;
  border-bottom: 1px solid var(--border);
}

.nav-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
}

.logo-text {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.05em;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.nav-links a:not(.active) {
  color: var(--text-muted);
  font-size: 0.9rem;
  font-weight: 500;
}

.nav-links a:hover {
  color: var(--text-main);
}

.lang-selector {
  position: relative;
}

.lang-btn {
  background: transparent;
  border: none;
  color: var(--text-main);
  cursor: pointer;
  font-family: inherit;
  font-size: 0.9rem;
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.lang-dropdown {
  position: absolute;
  top: 100%;
  right: 0;
  margin-top: 0.5rem;
  background-color: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 0.5rem 0;
  min-width: 150px;
  box-shadow: 0 10px 30px rgba(0,0,0,0.5);
}

.lang-dropdown a {
  display: block;
  padding: 0.5rem 1rem;
  color: var(--text-muted);
}

.lang-dropdown a:hover, .lang-dropdown a.active {
  color: var(--text-main);
  background-color: var(--bg-hover);
}

.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  color: var(--text-main);
  font-size: 1.5rem;
  cursor: pointer;
}

/* Hero Carousel */
.hero-carousel {
  position: relative;
  height: 90vh;
  min-height: 600px;
  overflow: hidden;
  display: flex;
  align-items: center;
}

.hero-slides {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
}

.slide {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.8s ease, visibility 0.8s ease;
  display: flex;
  align-items: center;
  background-size: cover;
  background-position: center;
}

.slide.active {
  opacity: 1;
  visibility: visible;
  z-index: 1;
}

/* Cinematic Placeholders */
.slide-bg-1 { background-image: linear-gradient(to right, rgba(10,10,10,0.9) 20%, rgba(10,10,10,0.3)), url('https://images.unsplash.com/photo-1550751827-4bd374c3f58b?auto=format&fit=crop&q=80&w=2000'); }
.slide-bg-2 { background-image: linear-gradient(to right, rgba(10,10,10,0.9) 20%, rgba(10,10,10,0.3)), url('https://images.unsplash.com/photo-1485827404703-89b55fcc595e?auto=format&fit=crop&q=80&w=2000'); }
.slide-bg-3 { background-image: linear-gradient(to right, rgba(10,10,10,0.9) 20%, rgba(10,10,10,0.3)), url('https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?auto=format&fit=crop&q=80&w=2000'); }
.slide-bg-4 { background-image: linear-gradient(to right, rgba(10,10,10,0.9) 20%, rgba(10,10,10,0.3)), url('https://images.unsplash.com/photo-1557804506-669a67965ba0?auto=format&fit=crop&q=80&w=2000'); }
.slide-bg-5 { background-image: linear-gradient(to right, rgba(10,10,10,0.9) 20%, rgba(10,10,10,0.3)), url('https://images.unsplash.com/photo-1460925895917-afdab827c52f?auto=format&fit=crop&q=80&w=2000'); }

.slide-content {
  position: relative;
  z-index: 2;
  max-width: 800px;
}

.slide-title {
  font-size: 4rem;
  margin-bottom: 1.5rem;
  line-height: 1.1;
}

.slide-desc {
  font-size: 1.25rem;
  color: #E0E0E0;
  margin-bottom: 2rem;
  max-width: 600px;
}

.hero-controls {
  position: absolute;
  bottom: 3rem;
  left: 0;
  right: 0;
  z-index: 10;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.hero-indicators {
  display: flex;
  gap: 0.75rem;
}

.dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background-color: rgba(255,255,255,0.3);
  border: none;
  cursor: pointer;
  transition: var(--transition);
}

.dot.active {
  background-color: var(--accent);
  transform: scale(1.2);
}

.nav-btn {
  background-color: rgba(255,255,255,0.1);
  border: 1px solid rgba(255,255,255,0.2);
  color: white;
  width: 48px;
  height: 48px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: var(--transition);
}

.nav-btn:hover {
  background-color: var(--accent);
  border-color: var(--accent);
}

.hero-nav-btns {
  display: flex;
  gap: 1rem;
}

/* Team Section */
.region-tabs {
  display: flex;
  gap: 2rem;
  margin-bottom: 3rem;
  border-bottom: 1px solid var(--border);
}

.tab-btn {
  background: transparent;
  border: none;
  color: var(--text-muted);
  font-size: 1.125rem;
  font-weight: 500;
  padding: 1rem 0;
  cursor: pointer;
  position: relative;
  font-family: inherit;
}

.tab-btn:hover {
  color: var(--text-main);
}

.tab-btn.active {
  color: var(--text-main);
}

.tab-btn.active::after {
  content: '';
  position: absolute;
  bottom: -1px;
  left: 0;
  width: 100%;
  height: 2px;
  background-color: var(--accent);
}

.team-carousel {
  display: flex;
  gap: 2rem;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none; /* Firefox */
  padding-bottom: 1rem;
}

.team-carousel::-webkit-scrollbar {
  display: none;
}

.team-card {
  min-width: 350px;
  background-color: var(--bg-card);
  border-radius: var(--radius-lg);
  overflow: hidden;
  scroll-snap-align: start;
  border: 1px solid var(--border);
  flex-shrink: 0;
}

.card-img {
  height: 250px;
  background-size: cover;
  background-position: center;
  background-color: #333;
}

/* Placeholder team images */
.team-img-1 { background-image: url('https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&q=80&w=800'); }
.team-img-2 { background-image: url('https://images.unsplash.com/photo-1560250097-0b93528c311a?auto=format&fit=crop&q=80&w=800'); }
.team-img-3 { background-image: url('https://images.unsplash.com/photo-1580489944761-15a19d654956?auto=format&fit=crop&q=80&w=800'); }
.team-img-4 { background-image: url('https://images.unsplash.com/photo-1519085360753-af0119f7cbe7?auto=format&fit=crop&q=80&w=800'); }
.team-img-5 { background-image: url('https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&q=80&w=800'); }
.team-img-6 { background-image: url('https://images.unsplash.com/photo-1598550874175-4d0ef436c909?auto=format&fit=crop&q=80&w=800'); }
.team-img-7 { background-image: url('https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&q=80&w=800'); }


.card-content {
  padding: 2rem;
  display: flex;
  flex-direction: column;
  height: calc(100% - 250px);
}

.quote {
  font-size: 1.125rem;
  font-style: italic;
  margin-bottom: 2rem;
  color: #E0E0E0;
  flex-grow: 1;
}

.author-info {
  margin-bottom: 1.5rem;
}

.author-name {
  font-size: 1.125rem;
  margin-bottom: 0.25rem;
}

.author-title {
  color: var(--text-muted);
  font-size: 0.875rem;
}

.contact-link {
  color: var(--accent);
  font-weight: 500;
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
}

.contact-link:hover {
  color: var(--accent-hover);
  transform: translateX(5px);
}

/* Work Showcase */
.work-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  margin-bottom: 3rem;
}

.work-nav {
  display: flex;
  gap: 1rem;
}

.work-carousel {
  display: flex;
  gap: 2rem;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  padding-bottom: 2rem;
}

.work-carousel::-webkit-scrollbar {
  display: none;
}

.work-card {
  min-width: 500px;
  scroll-snap-align: start;
  flex-shrink: 0;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background-color: var(--bg-card);
  border: 1px solid var(--border);
  transition: transform 0.3s ease;
}

.work-card:hover {
  transform: translateY(-5px);
}

.work-img {
  height: 300px;
  background-size: cover;
  background-position: center;
}

.work-bg-1 { background-image: url('https://images.unsplash.com/photo-1551288049-bebda4e38f71?auto=format&fit=crop&q=80&w=1000'); }
.work-bg-2 { background-image: url('https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&q=80&w=1000'); }
.work-bg-3 { background-image: url('https://images.unsplash.com/photo-1503375836287-3c3506169fc9?auto=format&fit=crop&q=80&w=1000'); }
.work-bg-4 { background-image: url('https://images.unsplash.com/photo-1556742049-0cfed4f6a45d?auto=format&fit=crop&q=80&w=1000'); }
.work-bg-5 { background-image: url('https://images.unsplash.com/photo-1618221195710-dd6b41faaea6?auto=format&fit=crop&q=80&w=1000'); }
.work-bg-6 { background-image: url('https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&q=80&w=1000'); }

.work-content {
  padding: 2rem;
}

.work-title {
  font-size: 1.5rem;
  margin-bottom: 0.5rem;
}

.work-client {
  color: var(--accent);
  font-weight: 500;
  margin-bottom: 1rem;
}

.work-quote {
  color: var(--text-muted);
  font-size: 0.95rem;
  margin-bottom: 1rem;
  font-style: italic;
}

.work-author {
  font-size: 0.85rem;
  color: #777;
}

/* How We Work Split */
.split-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}

.body-text {
  font-size: 1.25rem;
  color: var(--text-muted);
  margin-bottom: 2rem;
}

.how-img {
  height: 500px;
  background-image: url('https://images.unsplash.com/photo-1522071820081-009f0129c71c?auto=format&fit=crop&q=80&w=1000');
  background-size: cover;
  background-position: center;
  border-radius: var(--radius-lg);
}

/* Latest Insights */
.insights-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 2rem;
}

.insight-card {
  background-color: var(--bg-card);
  padding: 2rem;
  border-radius: var(--radius);
  border: 1px solid var(--border);
  display: flex;
  flex-direction: column;
}

.insight-card:hover {
  border-color: var(--text-muted);
}

.insight-card.highlight {
  background: linear-gradient(135deg, #1A1A1A, #122240);
  border-color: var(--accent);
}

.insight-meta {
  color: var(--accent);
  font-size: 0.875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 1rem;
}

.insight-title {
  font-size: 1.25rem;
  margin-bottom: 2rem;
  flex-grow: 1;
}

.insight-cta {
  font-weight: 500;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

/* Principles */
.principles-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 3rem;
  margin-top: 4rem;
}

.principle-card {
  padding: 2rem;
  background-color: var(--bg-card);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
}

.principle-number {
  font-size: 3rem;
  font-weight: 700;
  color: rgba(255,255,255,0.1);
  margin-bottom: 1rem;
}

.principle-title {
  font-size: 1.5rem;
  margin-bottom: 1rem;
}

.principle-desc {
  color: var(--text-muted);
}

/* CTA Section */
.section-cta {
  background: linear-gradient(to right, var(--bg-main), #111827, var(--bg-main));
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
}

.cta-title {
  font-size: 3.5rem;
  margin-bottom: 1.5rem;
}

.cta-body {
  font-size: 1.25rem;
  color: var(--text-muted);
  max-width: 600px;
  margin: 0 auto 2.5rem auto;
}

/* Footer */
.footer {
  background-color: var(--bg-main);
  padding: 4rem 0 2rem 0;
}

.footer-top {
  display: grid;
  grid-template-columns: 2fr 1.5fr 1.5fr 1fr;
  gap: 3rem;
  margin-bottom: 4rem;
}

.brand-col .footer-logo {
  font-size: 1.5rem;
  font-weight: 700;
  display: block;
  margin-bottom: 0.5rem;
}

.brand-col .footer-desc {
  color: var(--text-muted);
}

.footer-col h4 {
  margin-bottom: 1.5rem;
  font-size: 1.125rem;
}

.footer-col p {
  color: var(--text-muted);
  margin-bottom: 1.5rem;
}

.footer-link-action {
  color: var(--text-main);
  font-weight: 500;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.footer-link-action:hover {
  color: var(--accent);
}

.links-col a {
  display: block;
  color: var(--text-muted);
  margin-bottom: 0.75rem;
}

.links-col a:hover {
  color: var(--text-main);
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 2rem;
  border-top: 1px solid var(--border);
  color: var(--text-muted);
  font-size: 0.875rem;
}

.legal-links {
  display: flex;
  gap: 1.5rem;
}

.legal-links a:hover {
  color: var(--text-main);
}

/* Cookie Banner */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  width: 100%;
  background-color: rgba(30, 30, 30, 0.95);
  backdrop-filter: blur(10px);
  border-top: 1px solid var(--border);
  z-index: 1000;
  padding: 1.5rem 0;
  transform: translateY(100%);
  transition: transform 0.5s ease;
}

.cookie-banner.show {
  transform: translateY(0);
}

.cookie-content {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 5%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
}

.cookie-content p {
  font-size: 0.9rem;
  color: var(--text-muted);
  max-width: 800px;
}

.cookie-actions {
  display: flex;
  gap: 1rem;
}

/* Responsive */
@media (max-width: 1024px) {
  .slide-title { font-size: 3rem; }
  .split-layout { grid-template-columns: 1fr; }
  .how-img { height: 400px; order: -1; }
  .principles-grid { grid-template-columns: 1fr; }
  .footer-top { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 768px) {
  .nav-links {
    position: fixed;
    top: 80px;
    left: 0;
    width: 100%;
    background-color: var(--bg-main);
    flex-direction: column;
    padding: 2rem;
    gap: 1.5rem;
    border-bottom: 1px solid var(--border);
    transform: translateY(-150%);
    transition: transform 0.3s ease;
  }

  .nav-links.active {
    transform: translateY(0);
  }

  .mobile-menu-btn { display: block; }

  .slide-title { font-size: 2.25rem; }
  .section { padding: 4rem 0; }

  .work-card { min-width: 300px; }
  .team-card { min-width: 280px; }

  .cookie-content { flex-direction: column; align-items: flex-start; }
  .footer-top { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; gap: 1rem; text-align: center; }
}

document.addEventListener('DOMContentLoaded', () => {

  // Mobile Menu
  const mobileMenuBtn = document.querySelector('.mobile-menu-btn');
  const navLinks = document.querySelector('.nav-links');

  mobileMenuBtn.addEventListener('click', () => {
    navLinks.classList.toggle('active');
  });

  // Language Dropdown
  const langBtn = document.getElementById('lang-btn');
  const langDropdown = document.getElementById('lang-dropdown');

  langBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    langDropdown.classList.toggle('hidden');
  });

  document.addEventListener('click', () => {
    langDropdown.classList.add('hidden');
  });

  langDropdown.querySelectorAll('a').forEach(link => {
    link.addEventListener('click', (e) => {
      e.preventDefault();
      langDropdown.querySelectorAll('a').forEach(l => l.classList.remove('active'));
      e.target.classList.add('active');
      langBtn.innerHTML = `${e.target.textContent} <i class="ri-arrow-down-s-line"></i>`;
      langDropdown.classList.add('hidden');
    });
  });

  // Hero Carousel
  const slides = document.querySelectorAll('.slide');
  const dots = document.querySelectorAll('.dot');
  const prevBtn = document.getElementById('hero-prev');
  const nextBtn = document.getElementById('hero-next');
  let currentSlide = 0;
  let slideInterval;

  function showSlide(index) {
    slides.forEach(s => s.classList.remove('active'));
    dots.forEach(d => d.classList.remove('active'));

    currentSlide = index;
    if (currentSlide < 0) currentSlide = slides.length - 1;
    if (currentSlide >= slides.length) currentSlide = 0;

    slides[currentSlide].classList.add('active');
    dots[currentSlide].classList.add('active');
  }

  function nextSlide() {
    showSlide(currentSlide + 1);
  }

  function prevSlide() {
    showSlide(currentSlide - 1);
  }

  function startSlideShow() {
    slideInterval = setInterval(nextSlide, 6000);
  }

  function stopSlideShow() {
    clearInterval(slideInterval);
  }

  prevBtn.addEventListener('click', () => {
    prevSlide();
    stopSlideShow();
    startSlideShow();
  });

  nextBtn.addEventListener('click', () => {
    nextSlide();
    stopSlideShow();
    startSlideShow();
  });

  dots.forEach(dot => {
    dot.addEventListener('click', (e) => {
      const index = parseInt(e.target.dataset.index);
      showSlide(index);
      stopSlideShow();
      startSlideShow();
    });
  });

  startSlideShow();

  // Team Region Toggle
  const regionTabs = document.querySelectorAll('.tab-btn');
  const teamCards = document.querySelectorAll('.team-card');
  const teamCarousel = document.getElementById('team-carousel');

  regionTabs.forEach(tab => {
    tab.addEventListener('click', (e) => {
      // Update active tab
      regionTabs.forEach(t => t.classList.remove('active'));
      e.target.classList.add('active');

      const region = e.target.dataset.region;

      // Filter cards
      teamCards.forEach(card => {
        if (card.dataset.region === region) {
          card.style.display = 'block';
        } else {
          card.style.display = 'none';
        }
      });

      // Reset scroll
      teamCarousel.scrollTo({ left: 0, behavior: 'smooth' });
    });
  });

  // Work Carousel Navigation
  const workCarousel = document.getElementById('work-carousel');
  const workPrev = document.getElementById('work-prev');
  const workNext = document.getElementById('work-next');

  workPrev.addEventListener('click', () => {
    workCarousel.scrollBy({ left: -400, behavior: 'smooth' });
  });

  workNext.addEventListener('click', () => {
    workCarousel.scrollBy({ left: 400, behavior: 'smooth' });
  });

  // Cookie Consent
  const cookieBanner = document.getElementById('cookie-banner');
  const btnAccept = document.getElementById('cookie-accept');
  const btnManage = document.getElementById('cookie-manage');
  const btnDecline = document.getElementById('cookie-decline');

  // Check if cookie consent is already given
  if (!localStorage.getItem('cookieConsent')) {
    setTimeout(() => {
      cookieBanner.classList.add('show');
    }, 1500);
  }

  function hideBanner() {
    cookieBanner.classList.remove('show');
    localStorage.setItem('cookieConsent', 'true');
  }

  btnAccept.addEventListener('click', hideBanner);
  btnManage.addEventListener('click', hideBanner);
  btnDecline.addEventListener('click', hideBanner);
});
